/* MBM Property Manager V10
   Consolidated V1–V9 workspace. Every module reads from the same portfolio, lease,
   finance and operations records; no module maintains a disconnected copy. */
(() => {
  'use strict';
  const KEY = 'mbmPropertyManagerV10';
  const $ = s => document.querySelector(s);
  const $$ = s => [...document.querySelectorAll(s)];
  const today = () => new Date().toISOString().slice(0, 10);
  const uid = prefix => `${prefix}_${(crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).slice(2)).slice(0, 12)}`;
  const money = n => `N$ ${Number(n || 0).toLocaleString('en-NA', {minimumFractionDigits:2, maximumFractionDigits:2})}`;
  const esc = value => String(value ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const dateLabel = value => value ? new Intl.DateTimeFormat('en-NA',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${value}T00:00:00`)) : '—';
  const diffDays = value => value ? Math.ceil((new Date(`${value}T00:00:00`) - new Date(`${today()}T00:00:00`)) / 86400000) : null;
  const activeStatus = s => ['Active','Signed','Renewal in progress'].includes(s);

  const blankState = () => ({
    version: 10,
    organization: {name:'Musa Business Management CC', currency:'N$', timezone:'Africa/Windhoek'},
    properties: [], units: [], contacts: [], owners: [], prospects: [], listings: [], leases: [], invoices: [], payments: [], allocations: [], municipalAccounts: [], municipalPayments: [], renewals: [],
    vendors: [], workOrders: [], inspections: [], documents: [], tasks: [], calendarEvents: [], teamMembers: [], paymentArrangements: [], audit: [], ui: {view:'dashboard', report:'executive'}
  });
  let state = loadState();

  function parse(raw, fallback) { try { return JSON.parse(raw) ?? fallback; } catch { return fallback; } }
  function loadState() {
    const existing = parse(localStorage.getItem(KEY), null);
    if (existing?.version >= 1) return Object.assign(blankState(), existing, {version:10});
    const previous = parse(localStorage.getItem('mbmPropertyManagerV1'), null);
    if (previous?.version >= 1) return Object.assign(blankState(), previous, {version:10});
    const migrated = migrateLegacy();
    localStorage.setItem(KEY, JSON.stringify(migrated));
    return migrated;
  }
  function migrateLegacy() {
    const next = blankState();
    const oldProperties = parse(localStorage.getItem('mbmPropertyMaster'), []);
    const oldTenants = parse(localStorage.getItem('mbmTenantMaster'), []);
    const oldReceipts = parse(localStorage.getItem('mbmReceiptsContractFixed'), []);
    oldProperties.forEach((p, index) => next.properties.push({
      id: p.id || uid('property'), code:p.erf || `PROPERTY-${index + 1}`, name:p.name || [p.street,p.suburb].filter(Boolean).join(', ') || `Property ${index+1}`,
      erf:p.erf || '', address:[p.street,p.suburb,p.town].filter(Boolean).join(', '), type:p.type || 'Residential', status:p.status || 'Active', createdAt:today()
    }));
    if (!next.properties.length && (oldTenants.length || oldReceipts.length)) next.properties.push({id:'legacy_property',code:'ERF 3478',name:'Khomasdal - Shanghai Street',erf:'ERF 3478',address:'Shanghai Street, Khomasdal, Windhoek',type:'Mixed Use',status:'Active',createdAt:today()});
    const propertyId = id => next.properties.find(x => x.id === id)?.id || next.properties[0]?.id || '';
    oldTenants.forEach((tenant, ti) => {
      const contact = {id:uid('contact'),name:tenant.name || `Tenant ${ti+1}`,phone:tenant.contact || '',email:'',kind:'Tenant',createdAt:today()};
      next.contacts.push(contact);
      (tenant.units || []).forEach((oldUnit, ui) => {
        const pId = propertyId(oldUnit.propertyId || tenant.propertyId);
        const unit = {id:uid('unit'),propertyId:pId,name:oldUnit.unit || `Unit ${ui+1}`,type:'Rental Unit',status:'Occupied',marketRent:Number(oldUnit.rent)||0,createdAt:today()};
        next.units.push(unit);
        const lease = {id:uid('lease'),leaseNo:oldUnit.contractNo || `LEGACY-${ti+1}-${ui+1}`,propertyId:pId,unitId:unit.id,contactId:contact.id,status:oldUnit.contractIssued === 'No' ? 'Draft' : 'Active',startDate:oldUnit.contractStart || '',endDate:oldUnit.contractExpiry || '',monthlyRent:Number(oldUnit.rent)||0,escalation:0,deposit:0,noticeDays:60,agreementStatus:oldUnit.contractIssued || 'Unknown',createdAt:today()};
        next.leases.push(lease);
        if (oldUnit.contractFileName) next.documents.push({id:uid('doc'),leaseId:lease.id,name:oldUnit.contractFileName,type:'Lease document',status:'Legacy reference',expiryDate:'',createdAt:today()});
      });
    });
    oldReceipts.forEach((receipt, index) => {
      const tenantName = receipt.customer?.name || ''; const unitName = receipt.customer?.unit || '';
      const lease = next.leases.find(l => next.contacts.find(c=>c.id===l.contactId)?.name === tenantName && next.units.find(u=>u.id===l.unitId)?.name === unitName);
      const amount = Number(receipt.totals?.net || receipt.amount || 0);
      if (!amount) return;
      next.payments.push({id:uid('payment'),receiptNo:receipt.receiptNo || `LEGACY-R-${index+1}`,leaseId:lease?.id || '',propertyId:lease?.propertyId || propertyId(receipt.property?.id),paymentDate:receipt.receiptDate || today(),period:`${receipt.month || ''} ${receipt.year || ''}`.trim(),amount,method:receipt.paymentMethod || 'Legacy import',notes:receipt.notes || '',createdAt:today()});
    });
    const oldMunicipal = parse(localStorage.getItem('mbmMunicipalAccounts'), []);
    oldMunicipal.forEach(m => next.municipalAccounts.push({id:m.id||uid('municipal'),propertyId:propertyId(m.propertyId),accountNo:m.accountNo||m.accountNumber||'',balance:Number(m.balance||0),statementDate:m.statementDate||'',dueDate:m.dueDate||'',notes:m.notes||'',createdAt:today()}));
    const oldOperations = parse(localStorage.getItem('mbmOperationsData'), {workOrders:[],inspections:[]});
    (oldOperations.workOrders||[]).forEach(w => next.workOrders.push({id:w.id||uid('work'),propertyId:propertyId(w.propertyId),unitName:w.unit||w.unitName||'',title:w.title||w.category||'Work order',category:w.category||'Other',priority:w.priority||'Normal',assignee:w.assignee||'',dueDate:w.dueDate||'',status:w.status||'Open',notes:w.description||w.notes||'',quotedAmount:Number(w.quotedAmount||w.estimatedCost||0),actualCost:Number(w.actualCost||0),createdAt:today()}));
    (oldOperations.inspections||[]).forEach(i => next.inspections.push({id:i.id||uid('inspection'),propertyId:propertyId(i.propertyId),unitName:i.unit||i.unitName||'',type:i.type||'Routine inspection',date:i.scheduledDate||i.date||'',inspector:i.inspector||'',status:i.status||'Scheduled',notes:i.notes||'',conditionScore:i.conditionScore||'',defects:i.defects||'',createdAt:today()}));
    parse(localStorage.getItem('mbmRenewalCases'), []).forEach(r => { const l=next.leases.find(x=>x.leaseNo===r.contractNumber)||next.leases.find(x=>x.propertyId===propertyId(r.propertyId)); if(l) next.renewals.push({id:r.id||uid('renewal'),leaseId:l.id,stage:r.stage||'Expiry review',nextActionDate:r.nextActionDate||'',noticeDate:r.noticeDate||'',termMonths:Number(r.proposedTermMonths||r.termMonths||12),proposedRent:Number(r.proposedRent||r.proposedMonthlyRent||0),legalStatus:r.legalStatus||'Not started',approvalStatus:r.approvalStatus||r.managementStatus||'Not requested',agreementRef:r.agreementRef||r.newAgreementReference||'',signatureDate:r.signatureDate||'',billingDate:r.billingDate||r.billingActivationDate||'',notes:r.notes||'',createdAt:today()}); });
    parse(localStorage.getItem('mbmCalendarEvents'), []).forEach(e => next.calendarEvents.push({id:e.id||uid('event'),date:e.date||'',type:e.type||'Property event',title:e.title||'Management event',propertyId:propertyId(e.propertyId),notes:e.notes||'',createdAt:today()}));
    if (next.properties.length || next.contacts.length || next.payments.length || next.workOrders.length || next.renewals.length) audit(next, 'V1–V9 legacy migration', 'Imported all available portfolio, lease, receipt, municipal, operations, renewal and calendar records from the prior MBM releases.');
    return next;
  }
  function save(message = 'Changes saved locally') { localStorage.setItem(KEY, JSON.stringify(state)); $('#saveStatus').textContent = message; setTimeout(() => { $('#saveStatus').textContent = 'Local workspace'; }, 2800); }
  function audit(target, action, detail) { target.audit.unshift({id:uid('audit'),at:new Date().toISOString(),action,detail}); }
  const property = id => state.properties.find(x => x.id === id);
  const unit = id => state.units.find(x => x.id === id);
  const contact = id => state.contacts.find(x => x.id === id);
  const lease = id => state.leases.find(x => x.id === id);
  const vendor = id => state.vendors.find(x => x.id === id);
  const propertyName = id => { const r=property(id); return r ? `${r.code} · ${r.name}` : 'Unassigned'; };
  const leaseName = id => { const r=lease(id); if(!r) return 'Unassigned'; return `${r.leaseNo} · ${contact(r.contactId)?.name || 'Tenant'} · ${unit(r.unitId)?.name || 'Unit'}`; };
  function getActiveLeases() { return state.leases.filter(l => activeStatus(l.status)); }
  function monthlyDue() { return getActiveLeases().reduce((sum,l) => sum + Number(l.monthlyRent||0), 0); }
  function allocatedTo(chargeId) { return state.allocations.filter(a=>a.chargeId===chargeId).reduce((sum,a)=>sum+Number(a.amount||0),0); }
  function chargeBalance(charge) { return Math.max(0, Number(charge?.amount||0)-allocatedTo(charge?.id)); }
  function openCharges() { return state.invoices.filter(c=>chargeBalance(c)>0.009); }
  function openChargeBalance() { return openCharges().reduce((sum,c)=>sum+chargeBalance(c),0); }
  function depositHeld() { return getActiveLeases().reduce((sum,l)=>sum+Number(l.deposit||0),0); }
  function monthPayments(date = today()) { const prefix = date.slice(0,7); return state.payments.filter(p => String(p.paymentDate).slice(0,7) === prefix).reduce((sum,p) => sum + Number(p.amount||0),0); }
  function municipalOwing() { return state.municipalAccounts.reduce((sum,m) => sum + Number(m.balance||0),0); }
  function openWork() { return state.workOrders.filter(w => w.status !== 'Completed'); }
  function leaseExpiry() { return getActiveLeases().filter(l => {const d=diffDays(l.endDate); return d !== null && d <= 90;}).sort((a,b) => (a.endDate||'').localeCompare(b.endDate||'')); }
  function occupancy() { const occupied = state.units.filter(u=>u.status==='Occupied').length; return {occupied,total:state.units.length,rate:state.units.length ? Math.round(occupied/state.units.length*100):0}; }
  function complianceIssues() {
    const issues=[];
    state.leases.forEach(l=>{ if(activeStatus(l.status) && !l.endDate) issues.push({kind:'Contract control',name:leaseName(l.id),detail:'Active lease has no expiry date',level:'red'}); });
    leaseExpiry().forEach(l=>issues.push({kind:'Lease expiry',name:leaseName(l.id),detail:diffDays(l.endDate)<0?'Lease has expired':`${diffDays(l.endDate)} days remaining`,level:diffDays(l.endDate)<0?'red':'gold'}));
    state.renewals.filter(r=>r.nextActionDate && diffDays(r.nextActionDate)<0 && !['Renewed / billing activated','Non-renewal / exit'].includes(r.stage)).forEach(r=>issues.push({kind:'Renewal action',name:leaseName(r.leaseId),detail:`Next action overdue: ${dateLabel(r.nextActionDate)}`,level:'red'}));
    state.municipalAccounts.filter(m=>m.dueDate && diffDays(m.dueDate)<0 && Number(m.balance)>0).forEach(m=>issues.push({kind:'Municipal account',name:propertyName(m.propertyId),detail:`${money(m.balance)} overdue`,level:'red'}));
    openCharges().filter(c=>c.dueDate && diffDays(c.dueDate)<0).forEach(c=>issues.push({kind:'Collections exception',name:leaseName(c.leaseId),detail:`${money(chargeBalance(c))} overdue · ${c.description||c.type||'charge'}`,level:'red'}));
    state.inspections.filter(i=>i.status==='Completed' && i.defects && !i.followUpDue).forEach(i=>issues.push({kind:'Inspection control',name:propertyName(i.propertyId),detail:'Defects recorded without a follow-up due date',level:'gold'}));
    return issues;
  }
  function eventItems() {
    const list=[];
    state.leases.forEach(l=>l.endDate && list.push({date:l.endDate,kind:'contract',label:`Contract expiry: ${leaseName(l.id)}`,level:'gold'}));
    state.renewals.forEach(r=>r.nextActionDate && list.push({date:r.nextActionDate,kind:'renewal',label:`Renewal: ${leaseName(r.leaseId)}`,level:'gold'}));
    state.municipalAccounts.forEach(m=>m.dueDate && Number(m.balance)>0 && list.push({date:m.dueDate,kind:'municipal',label:`Municipal due: ${propertyName(m.propertyId)}`,level:'red'}));
    state.workOrders.filter(w=>w.status!=='Completed').forEach(w=>w.dueDate && list.push({date:w.dueDate,kind:'work',label:`Work order: ${w.title}`,level:w.priority==='Urgent'?'red':'blue'}));
    state.inspections.filter(i=>i.status!=='Completed').forEach(i=>i.date && list.push({date:i.date,kind:'inspection',label:`Inspection: ${i.type}`,level:'blue'}));
    state.tasks.forEach(t=>t.date && list.push({date:t.date,kind:'task',label:t.title,level:'blue'}));
    state.calendarEvents.forEach(e=>e.date && list.push({date:e.date,kind:'event',label:e.title,level:'blue'}));
    return list.sort((a,b)=>a.date.localeCompare(b.date));
  }

  function setView(view) { state.ui.view = view; save('Workspace updated'); render(); history.replaceState(null,'',`#${view}`); }
  function render() {
    const availableViews=['dashboard','calendar','portfolio','people','leases','renewals','finance','municipal','operations','documents','reports','admin'];
    const view = availableViews.includes(state.ui.view) ? state.ui.view : 'dashboard';
    state.ui.view=view;
    $$('.nav-link').forEach(btn=>btn.classList.toggle('active',btn.dataset.view===view));
    const meta = {
      dashboard:['COMMAND CENTRE','Property management dashboard'],calendar:['COMMAND CENTRE','Calendar & Tasks'],portfolio:['PORTFOLIO & LEASING','Portfolio & Units'],people:['PORTFOLIO & LEASING','People & Vacancies'],leases:['PORTFOLIO & LEASING','Leases & Contracts'],renewals:['PORTFOLIO & LEASING','Renewals & Approvals'],finance:['FINANCE & OPERATIONS','Billing, Payments & Receipts'],municipal:['FINANCE & OPERATIONS','Municipal Accounts'],operations:['OPERATIONS','Maintenance & Inspections'],documents:['GOVERNANCE','Documents & Compliance'],reports:['GOVERNANCE','Reports & Insights'],admin:['SETTINGS','Administration']
    }[view];
    $('#eyebrow').textContent=meta[0]; $('#pageTitle').textContent=meta[1];
    $('#app').innerHTML = ({dashboard:renderDashboard,calendar:renderCalendar,portfolio:renderPortfolio,people:renderPeople,leases:renderLeases,renewals:renderRenewals,finance:renderFinance,municipal:renderMunicipal,operations:renderOperations,documents:renderDocuments,reports:renderReports,admin:renderAdmin}[view])();
    bindView();
  }
  const head = (title, description, actions='') => `<div class="view-head"><div><h2>${title}</h2><p>${description}</p></div><div class="view-actions">${actions}</div></div>`;
  const badge = (label, level='grey') => `<span class="badge ${level}">${esc(label)}</span>`;
  const noRows = (span, text='No records yet. Add the first record to begin.') => `<tr><td colspan="${span}"><div class="empty">${text}</div></td></tr>`;

  function renderDashboard() {
    const occ=occupancy(), due=monthlyDue(), paid=monthPayments(), arrears=Math.max(0,due-paid), exp=leaseExpiry(), issues=complianceIssues(), recent=state.payments.slice().sort((a,b)=>b.paymentDate.localeCompare(a.paymentDate)).slice(0,6);
    return `${head('Property management dashboard','Your trusted workspace for properties, tenants, rent, maintenance and reports.',`<button class="secondary" data-action="form" data-type="payment">Record payment</button><button class="primary" data-action="form" data-type="lease">Add lease</button>`)}
      <section class="property-hero"><div class="hero-copy"><span class="eyebrow">YOUR TRUSTED PROPERTY PARTNER</span><h2>Managing Properties. Building Value.</h2><p>Musa Business Management CC · Property &amp; Rental Management</p><span class="phone">081 424 4350</span></div><div class="hero-art" aria-hidden="true"><span class="roof"></span><span class="home"></span><span class="door"></span><span class="window"></span><span class="window two"></span></div></section>
      <div class="kpis"><div class="kpi"><label>Portfolio occupancy</label><strong>${occ.rate}%</strong><small>${occ.occupied} of ${occ.total} units occupied</small></div><div class="kpi"><label>Active monthly lease value</label><strong>${money(due)}</strong><small>${getActiveLeases().length} active leases</small></div><div class="kpi ${arrears?'warn':''}"><label>Current month collections</label><strong>${money(paid)}</strong><small>${arrears?`${money(arrears)} still outstanding`:'No current-month gap'}</small></div><div class="kpi ${municipalOwing()?'danger':''}"><label>Municipal exposure</label><strong>${money(municipalOwing())}</strong><small>${state.municipalAccounts.length} tracked property account(s)</small></div></div>
      <div class="grid two"><section class="panel"><div class="panel-head"><h3>Management action centre</h3><button class="link-button" data-view="documents">Open compliance</button></div><div class="panel-body"><ul class="action-list">${issues.slice(0,7).map(i=>`<li><div><b>${esc(i.kind)} · ${esc(i.name)}</b><span>${esc(i.detail)}</span></div>${badge(i.level==='red'?'Action required':'Review',i.level)}</li>`).join('') || '<li><span>All monitored controls are currently clear.</span></li>'}</ul></div></section>
      <section class="panel"><div class="panel-head"><h3>Portfolio performance</h3><button class="link-button" data-view="reports">Open reports</button></div><div class="panel-body"><div class="list-kpi"><span>Expected monthly rent</span><strong>${money(due)}</strong></div><div class="list-kpi"><span>Payments recorded this month</span><strong>${money(paid)}</strong></div><div class="list-kpi"><span>Open work orders</span><strong>${openWork().length}</strong></div><div class="list-kpi"><span>Renewals within 90 days</span><strong>${exp.length}</strong></div><div class="list-kpi"><span>Compliance exceptions</span><strong>${issues.length}</strong></div></div></section></div>
      <div class="grid two" style="margin-top:18px"><section class="panel"><div class="panel-head"><h3>Recent payment activity</h3><button class="link-button" data-view="finance">View collections</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Receipt</th><th>Lease / tenant</th><th>Date</th><th>Amount</th></tr></thead><tbody>${recent.map(p=>`<tr><td class="main">${esc(p.receiptNo)}</td><td>${esc(leaseName(p.leaseId))}</td><td>${dateLabel(p.paymentDate)}</td><td>${money(p.amount)}</td></tr>`).join('')||noRows(4,'No payments have been recorded.')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h3>Lease and renewal watchlist</h3><button class="link-button" data-view="renewals">Manage renewals</button></div><div class="panel-body"><ul class="action-list">${exp.slice(0,6).map(l=>`<li><div><b>${esc(leaseName(l.id))}</b><span>Expires ${dateLabel(l.endDate)} • ${diffDays(l.endDate)} days</span></div>${badge(l.status,'gold')}</li>`).join('')||'<li><span>No active lease expires in the next 90 days.</span></li>'}</ul></div></section></div>`;
  }
  function renderPortfolio() {
    const rows=state.properties.map(p=>{const units=state.units.filter(u=>u.propertyId===p.id);const occupied=units.filter(u=>u.status==='Occupied').length;return `<tr><td><span class="main">${esc(p.code)}</span><span class="sub">${esc(p.name)}</span></td><td>${esc(p.address||'—')}</td><td>${esc(p.type)}</td><td>${occupied}/${units.length} occupied</td><td>${badge(p.status,p.status==='Active'?'green':'grey')}</td><td class="actions"><button class="link-button" data-action="form" data-type="property" data-id="${p.id}">Edit</button> · <button class="link-button" data-action="form" data-type="unit" data-property="${p.id}">Add unit</button></td></tr>`;}).join('');
    const units=state.units.map(u=>`<tr><td class="main">${esc(u.name)}</td><td>${esc(propertyName(u.propertyId))}</td><td>${esc(u.type)}</td><td>${money(u.marketRent)}</td><td>${badge(u.status,u.status==='Occupied'?'blue':u.status==='Vacant'?'gold':'grey')}</td><td class="actions"><button class="link-button" data-action="form" data-type="unit" data-id="${u.id}">Edit</button></td></tr>`).join('');
    return `${head('Portfolio and units','Maintain the master record that every lease, municipal account, work order and report uses.',`<button class="secondary" data-action="form" data-type="unit">Add unit</button><button class="primary" data-action="form" data-type="property">Add property</button>`)}<div class="callout info">Property and unit records are shared master data. Do not recreate a property when adding a lease, municipal bill or work order.</div><div class="grid equal"><section class="panel"><div class="panel-head"><h3>Property register</h3><span>${state.properties.length} property record(s)</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Property</th><th>Address</th><th>Type</th><th>Occupancy</th><th>Status</th><th></th></tr></thead><tbody>${rows||noRows(6)}</tbody></table></div></section><section class="panel"><div class="panel-head"><h3>Unit register</h3><span>${state.units.length} unit record(s)</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Unit</th><th>Property</th><th>Type</th><th>Market rent</th><th>Status</th><th></th></tr></thead><tbody>${units||noRows(6)}</tbody></table></div></section></div>`;
  }
  function renderPeople() {
    const vacant=state.units.filter(u=>u.status==='Vacant');
    const owners=state.owners.map(o=>`<tr><td class="main">${esc(o.name)}</td><td>${esc(o.phone||'—')}</td><td>${esc(o.email||'—')}</td><td>${esc(propertyName(o.propertyId))}</td><td>${esc(o.status||'Active')}</td><td><button class="link-button" data-action="form" data-type="owner" data-id="${o.id}">Edit</button></td></tr>`).join('');
    const prospects=state.prospects.map(p=>`<tr><td class="main">${esc(p.name)}</td><td>${esc(p.phone||'—')}</td><td>${esc(propertyName(p.propertyId))}</td><td>${esc(p.unitName||'Any vacant unit')}</td><td>${badge(p.stage,p.stage==='Approved'?'green':p.stage==='Declined'?'grey':'gold')}</td><td>${dateLabel(p.followUpDate)}</td><td><button class="link-button" data-action="form" data-type="prospect" data-id="${p.id}">Edit</button></td></tr>`).join('');
    const listings=vacant.map(u=>{const l=state.listings.find(x=>x.unitId===u.id);return `<tr><td class="main">${esc(propertyName(u.propertyId))}<span class="sub">${esc(u.name)}</span></td><td>${money(u.marketRent)}</td><td>${esc(l?.availableDate||'Available now')}</td><td>${badge(l?.status||'Not listed',l?.status==='Available'?'green':'grey')}</td><td>${state.prospects.filter(p=>p.unitId===u.id||(!p.unitId&&p.propertyId===u.propertyId)).length}</td><td><button class="link-button" data-action="form" data-type="listing" data-id="${l?.id||''}" data-unit="${u.id}">${l?'Edit listing':'Create listing'}</button></td></tr>`;}).join('');
    return `${head('People and vacancies','A lightweight leasing pipeline: owners, prospects and vacant units all use the same portfolio and unit data.',`<button class="secondary" data-action="form" data-type="owner">Add owner</button><button class="secondary" data-action="form" data-type="prospect">Add prospect</button><button class="primary" data-action="form" data-type="listing">Create vacancy listing</button>`)}<div class="grid equal"><section class="panel"><div class="panel-head"><h3>Owner directory</h3><span>${state.owners.length} owner(s)</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Owner</th><th>Phone</th><th>Email</th><th>Primary property</th><th>Status</th><th></th></tr></thead><tbody>${owners||noRows(6,'Add owners for managed properties when owner reporting is needed.')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h3>Prospect pipeline</h3><span>${state.prospects.filter(p=>!['Declined','Leased'].includes(p.stage)).length} open</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Prospect</th><th>Phone</th><th>Property</th><th>Unit interest</th><th>Stage</th><th>Follow-up</th><th></th></tr></thead><tbody>${prospects||noRows(7,'Capture leads and follow-up dates before converting a prospect to a lease.')}</tbody></table></div></section></div><section class="panel" style="margin-top:18px"><div class="panel-head"><h3>Vacancy board</h3><span>${vacant.length} vacant unit(s)</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Property / unit</th><th>Market rent</th><th>Available from</th><th>Listing status</th><th>Interested prospects</th><th></th></tr></thead><tbody>${listings||noRows(6,'Update a unit to Vacant to place it on the vacancy board.')}</tbody></table></div></section>`;
  }
  function renderLeases() {
    const rows=state.leases.map(l=>{const days=diffDays(l.endDate);const docCount=state.documents.filter(d=>d.leaseId===l.id).length;return `<tr><td><span class="main">${esc(l.leaseNo)}</span><span class="sub">${esc(contact(l.contactId)?.name||'No tenant')}</span></td><td>${esc(propertyName(l.propertyId))}<span class="sub">${esc(unit(l.unitId)?.name||'No unit')}</span></td><td>${money(l.monthlyRent)}</td><td>${dateLabel(l.endDate)}${days!==null?`<span class="sub">${days<0?'Expired':`${days} days left`}</span>`:''}</td><td>${badge(l.status,l.status==='Active'?'green':l.status==='Draft'?'grey':'gold')}</td><td>${docCount} file(s)</td><td class="actions"><button class="link-button" data-action="form" data-type="lease" data-id="${l.id}">Edit</button> · <button class="link-button" data-action="form" data-type="document" data-lease="${l.id}">Document</button></td></tr>`;}).join('');
    return `${head('Leases and contracts','The controlled agreement register. Lease values feed finance, expiries feed renewals and calendar, and documents feed compliance.',`<button class="primary" data-action="form" data-type="lease">Add lease</button>`)}<div class="kpis"><div class="kpi"><label>Active leases</label><strong>${getActiveLeases().length}</strong><small>Signed or active agreements</small></div><div class="kpi warn"><label>Expiring in 90 days</label><strong>${leaseExpiry().length}</strong><small>Require renewal/exit review</small></div><div class="kpi"><label>Documented leases</label><strong>${state.leases.filter(l=>state.documents.some(d=>d.leaseId===l.id)).length}</strong><small>At least one linked document</small></div><div class="kpi"><label>Monthly contracted rent</label><strong>${money(monthlyDue())}</strong><small>Active lease register total</small></div></div><section class="panel"><div class="panel-head"><h3>Lease register</h3><button class="link-button" data-view="renewals">Open renewal pipeline</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Lease / tenant</th><th>Property / unit</th><th>Monthly rent</th><th>Expiry</th><th>Status</th><th>Documents</th><th></th></tr></thead><tbody>${rows||noRows(7,'Add a property and unit first, then create the lease.')}</tbody></table></div></section>`;
  }
  function renderRenewals() {
    const rows=state.renewals.map(r=>{const l=lease(r.leaseId), days=diffDays(l?.endDate);return `<tr><td><span class="main">${esc(leaseName(r.leaseId))}</span><span class="sub">Expiry ${dateLabel(l?.endDate)}${days!==null?` · ${days<0?'expired':`${days} days`}`:''}</span></td><td>${badge(r.stage,r.stage.includes('Renewed')?'green':r.stage.includes('Non')?'grey':'gold')}</td><td>${dateLabel(r.nextActionDate)}</td><td>${esc(r.legalStatus||'Not started')}</td><td>${esc(r.approvalStatus||'Not requested')}</td><td>${r.proposedRent?money(r.proposedRent):'—'}</td><td class="actions"><button class="link-button" data-action="renewal-whatsapp" data-id="${r.id}">WhatsApp</button> · <button class="link-button" data-action="form" data-type="renewal" data-id="${r.id}">Edit</button></td></tr>`;}).join('');
    return `${head('Renewals and approvals','A renewal does not change the active lease until legal review, management approval, signature and billing activation are recorded.',`<button class="primary" data-action="form" data-type="renewal">Start renewal case</button>`)}<div class="callout">Control gate: retain the old agreement until the new agreement reference, signed date, legal approval, management approval and billing activation are complete.</div><section class="panel"><div class="panel-head"><h3>Renewal pipeline</h3><span>${state.renewals.length} case(s)</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Lease</th><th>Pipeline stage</th><th>Next action</th><th>Legal review</th><th>Management</th><th>Proposed rent</th><th></th></tr></thead><tbody>${rows||noRows(7,'Start a case from an expiring lease before the notice date.')}</tbody></table></div></section>`;
  }
  function renderFinance() {
    const due=monthlyDue(), paid=monthPayments(), estimatedGap=Math.max(0,due-paid);
    const rows=state.payments.slice().sort((a,b)=>String(b.paymentDate).localeCompare(String(a.paymentDate))).map(p=>`<tr><td class="main">${esc(p.receiptNo)}</td><td>${esc(leaseName(p.leaseId))}</td><td>${dateLabel(p.paymentDate)}<span class="sub">${esc(p.period||'')}</span></td><td>${esc(p.method)}</td><td>${money(p.amount)}</td><td class="actions"><button class="link-button" data-action="receipt" data-id="${p.id}">Print</button> · <button class="link-button" data-action="whatsapp" data-id="${p.id}">WhatsApp</button></td></tr>`).join('');
    const charges=openCharges().sort((a,b)=>String(a.dueDate||a.chargeDate).localeCompare(String(b.dueDate||b.chargeDate))).map(c=>`<tr><td class="main">${esc(leaseName(c.leaseId))}</td><td>${esc(c.type||'Rent')}</td><td>${esc(c.description||'—')}</td><td>${dateLabel(c.dueDate||c.chargeDate)}</td><td>${money(c.amount)}</td><td>${money(allocatedTo(c.id))}</td><td>${money(chargeBalance(c))}</td></tr>`).join('');
    return `${head('Billing, payments and receipts','The V1–V9 receipt workflow is retained and now feeds a charge, allocation and arrears register. Import historical payments when moving from older records.',`<button class="secondary" data-action="history-import">Import payment history</button><button class="secondary" data-action="form" data-type="charge">Record charge</button><button class="primary" data-action="form" data-type="payment">Record payment</button>`)}<div class="kpis"><div class="kpi"><label>Expected monthly rent</label><strong>${money(due)}</strong><small>Active lease value</small></div><div class="kpi"><label>Payments this month</label><strong>${money(paid)}</strong><small>${state.payments.filter(p=>String(p.paymentDate).slice(0,7)===today().slice(0,7)).length} receipt(s)</small></div><div class="kpi ${openChargeBalance()?'warn':''}"><label>Open billed balance</label><strong>${money(openChargeBalance())}</strong><small>From recorded charges less allocations</small></div><div class="kpi"><label>Deposit held</label><strong>${money(depositHeld())}</strong><small>Across active leases</small></div></div><div class="callout info">Uncollected estimate for this month: ${money(estimatedGap)}. For a legally traceable arrears figure, record charges and allocate the received payment to the charge.</div><div class="grid two"><section class="panel"><div class="panel-head"><h3>Open charge and arrears register</h3><button class="link-button" data-view="reports" data-report="finance">Finance report</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Lease / tenant</th><th>Type</th><th>Description</th><th>Due</th><th>Charge</th><th>Allocated</th><th>Open</th></tr></thead><tbody>${charges||noRows(7,'Record a rent, utility, deposit or other charge to track an outstanding balance.')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h3>Payment and receipt history</h3><span>${state.payments.length} receipt(s)</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Receipt</th><th>Lease / tenant</th><th>Date / period</th><th>Method</th><th>Amount</th><th></th></tr></thead><tbody>${rows||noRows(6,'Record a payment or import historic receipts.')}</tbody></table></div></section></div>`;
  }
  function renderMunicipal() {
    const rows=state.municipalAccounts.map(m=>`<tr><td class="main">${esc(propertyName(m.propertyId))}</td><td>${esc(m.accountNo||'—')}</td><td>${dateLabel(m.statementDate)}</td><td>${dateLabel(m.dueDate)}</td><td>${money(m.balance)}</td><td>${m.dueDate&&diffDays(m.dueDate)<0&&Number(m.balance)>0?badge('Overdue','red'):badge('Current','green')}</td><td class="actions"><button class="link-button" data-action="form" data-type="municipal-payment" data-id="${m.id}">Payment</button> · <button class="link-button" data-action="form" data-type="municipal" data-id="${m.id}">Edit</button></td></tr>`).join('');
    const payments=state.municipalPayments.slice().sort((a,b)=>String(b.paymentDate).localeCompare(String(a.paymentDate))).slice(0,10).map(p=>`<tr><td>${dateLabel(p.paymentDate)}</td><td class="main">${esc(propertyName(p.propertyId))}</td><td>${esc(p.reference||'—')}</td><td>${money(p.amount)}</td></tr>`).join('');
    return `${head('Municipal accounts','One current account per property, current statement balance and payment record. It remains a manual control until an authorised municipal API is available.',`<button class="secondary" data-action="municipal-export">Export municipal data</button><button class="primary" data-action="form" data-type="municipal">Add or update bill</button>`)}<div class="summary-strip"><div><h2>${money(municipalOwing())} total municipal exposure</h2><p>Current balances from the latest statements recorded for each property. A future municipality connection will use this same property/account link.</p></div><div class="right">Tracked accounts<br><b>${state.municipalAccounts.length}</b></div></div><div class="grid two"><section class="panel"><div class="panel-head"><h3>Municipal account register</h3><span>Manual, controlled record</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Property</th><th>Account no.</th><th>Statement</th><th>Due date</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody>${rows||noRows(7,'Add one current account/bill for each managed property.')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h3>Recent municipal payments</h3><span>${state.municipalPayments.length} recorded</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Property</th><th>Reference</th><th>Amount</th></tr></thead><tbody>${payments||noRows(4,'Record a payment against an account to preserve the balance history.')}</tbody></table></div></section></div>`;
  }
  function renderOperations() {
    const works=state.workOrders.map(w=>`<tr><td><span class="main">${esc(w.title)}</span><span class="sub">${esc(propertyName(w.propertyId))} · ${esc(w.unitName||'Common area')} · ${esc(w.category||'General')}</span></td><td>${esc(vendor(w.vendorId)?.name||w.assignee||'Unassigned')}</td><td>${dateLabel(w.dueDate)}</td><td>${money(w.quotedAmount||0)}<span class="sub">Actual ${money(w.actualCost||0)}</span></td><td>${badge(w.priority,w.priority==='Urgent'?'red':w.priority==='High'?'gold':'blue')} ${badge(w.status,w.status==='Completed'?'green':'grey')}</td><td class="actions"><button class="link-button" data-action="form" data-type="work" data-id="${w.id}">Edit</button> · <button class="link-button" data-action="complete-work" data-id="${w.id}">${w.status==='Completed'?'Reopen':'Complete'}</button></td></tr>`).join('');
    const inspections=state.inspections.map(i=>`<tr><td><span class="main">${esc(i.type)}</span><span class="sub">${esc(propertyName(i.propertyId))} · ${esc(i.unitName||'Common area')}</span></td><td>${dateLabel(i.date)}</td><td>${esc(i.inspector||'Unassigned')}</td><td>${esc(i.conditionScore||'—')}/5<span class="sub">${esc(i.defects||'No defects logged')}</span></td><td>${badge(i.status,i.status==='Completed'?'green':'gold')}</td><td class="actions"><button class="link-button" data-action="form" data-type="inspection" data-id="${i.id}">Edit</button> · <button class="link-button" data-action="complete-inspection" data-id="${i.id}">${i.status==='Completed'?'Reopen':'Complete'}</button></td></tr>`).join('');
    const vendors=state.vendors.map(v=>`<tr><td class="main">${esc(v.name)}</td><td>${esc(v.trade||'General')}</td><td>${esc(v.phone||'—')}</td><td>${esc(v.email||'—')}</td><td>${esc(v.status||'Active')}</td><td><button class="link-button" data-action="form" data-type="vendor" data-id="${v.id}">Edit</button></td></tr>`).join('');
    return `${head('Maintenance and inspections','Maintenance, vendor cost, inspection evidence and unit-turn controls feed the calendar, compliance queue and management reports.',`<button class="secondary" data-action="form" data-type="vendor">Add supplier</button><button class="secondary" data-action="form" data-type="inspection">Schedule inspection</button><button class="primary" data-action="form" data-type="work">Create work order</button>`)}<div class="grid equal"><section class="panel"><div class="panel-head"><h3>Work order register</h3><span>${openWork().length} open</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Work order</th><th>Supplier / owner</th><th>Due</th><th>Quote / actual</th><th>Status</th><th></th></tr></thead><tbody>${works||noRows(6,'Create a work order for repairs, safety issues or tenant requests.')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h3>Inspection register</h3><span>${state.inspections.filter(i=>i.status!=='Completed').length} scheduled</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Inspection</th><th>Date</th><th>Inspector</th><th>Condition / defects</th><th>Status</th><th></th></tr></thead><tbody>${inspections||noRows(6,'Schedule routine, move-in, move-out or safety inspections.')}</tbody></table></div></section></div><section class="panel" style="margin-top:18px"><div class="panel-head"><h3>Supplier directory</h3><span>${state.vendors.length} supplier(s)</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Supplier</th><th>Trade</th><th>Phone</th><th>Email</th><th>Status</th><th></th></tr></thead><tbody>${vendors||noRows(6,'Add approved suppliers before assigning work orders.')}</tbody></table></div></section>`;
  }
  function renderDocuments() {
    const issues=complianceIssues(); const rows=state.documents.map(d=>`<tr><td><span class="main">${esc(d.name)}</span><span class="sub">${esc(d.type)}</span></td><td>${esc(leaseName(d.leaseId))}<span class="sub">${esc(propertyName(d.propertyId))}</span></td><td>${esc(d.status||'Current')}</td><td>${dateLabel(d.expiryDate)}</td><td>${esc(d.storagePath?'Private vault':'Register only')}</td><td class="actions">${d.storagePath?`<button class="link-button" data-action="document-open" data-id="${d.id}">Open</button> · `:''}<button class="link-button" data-action="form" data-type="document" data-id="${d.id}">Edit</button></td></tr>`).join('');
    return `${head('Documents and compliance','A controlled register for agreements, notices, evidence and supporting records. Files can be transferred to private Supabase Storage when the cloud connector is enabled.',`<button class="primary" data-action="form" data-type="document">Register document</button>`)}<div class="grid two"><section class="panel"><div class="panel-head"><h3>Compliance exception register</h3><span>${issues.length} open</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Control area</th><th>Record</th><th>Exception</th><th>Priority</th></tr></thead><tbody>${issues.map(i=>`<tr><td>${esc(i.kind)}</td><td class="main">${esc(i.name)}</td><td>${esc(i.detail)}</td><td>${badge(i.level==='red'?'Action required':'Review',i.level)}</td></tr>`).join('')||noRows(4,'No compliance exceptions currently detected.')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h3>Document vault register</h3><span>${state.documents.length} record(s)</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Document</th><th>Lease / property</th><th>Status</th><th>Review</th><th>Storage</th><th></th></tr></thead><tbody>${rows||noRows(6,'Register lease contracts, notices, municipal statements, supplier quotes and inspection evidence.')}</tbody></table></div></section></div>`;
  }
  function renderCalendar() {
    const now=new Date(), year=now.getFullYear(), month=now.getMonth(), days=new Date(year,month+1,0).getDate(), first=new Date(year,month,1).getDay(), events=eventItems();let cells='';
    for(let x=0;x<first;x++)cells+='<div class="calendar-day"></div>'; for(let d=1;d<=days;d++){const ds=`${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;const e=events.filter(v=>v.date===ds).slice(0,3);cells+=`<div class="calendar-day"><b>${d}</b>${e.map(v=>`<span class="calendar-item ${v.level==='red'?'danger':v.level==='gold'?'warn':''}" title="${esc(v.label)}">${esc(v.label)}</span>`).join('')}</div>`;}
    return `${head('Calendar and tasks','One schedule generated from lease expiry, renewals, municipal due dates, work orders, inspections and manual property events.',`<button class="secondary" data-action="calendar-export">Export .ics</button><button class="secondary" data-action="form" data-type="event">Add property event</button><button class="primary" data-action="form" data-type="task">Add management task</button>`)}<section class="panel"><div class="panel-head"><h3>${new Intl.DateTimeFormat('en-NA',{month:'long',year:'numeric'}).format(now)}</h3><span>${events.length} scheduled item(s)</span></div><div class="panel-body"><div class="calendar-grid"><div><b>Sun</b></div><div><b>Mon</b></div><div><b>Tue</b></div><div><b>Wed</b></div><div><b>Thu</b></div><div><b>Fri</b></div><div><b>Sat</b></div>${cells}</div></div></section><section class="panel" style="margin-top:18px"><div class="panel-head"><h3>Upcoming agenda</h3></div><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Source</th><th>Activity</th></tr></thead><tbody>${events.filter(e=>e.date>=today()).slice(0,20).map(e=>`<tr><td>${dateLabel(e.date)}</td><td>${esc(e.kind)}</td><td class="main">${esc(e.label)}</td></tr>`).join('')||noRows(3,'No dated activities in the current workspace.')}</tbody></table></div></section>`;
  }
  function renderReports() {
    const r=state.ui.report||'executive'; const definitions={executive:['Executive portfolio report','Occupancy, revenue, municipal exposure, cost and management exceptions.'],finance:['Collections and arrears report','Charges, allocations, receipts, deposits and open balance.'],leases:['Lease expiry and renewal report','Expiring leases, countdowns, renewal stages and approval controls.'],vacancy:['Vacancy and prospect report','Vacant units, asking rent, listing status and pipeline follow-up.'],operations:['Operations performance report','Open work, vendor cost, inspections and priority exceptions.'],compliance:['Compliance and assurance report','Contract, expiry, renewal, municipal and inspection exceptions.'],municipal:['Municipal exposure report','Current balances, due dates, payment history and future API mapping.'],documents:['Document-control report','Agreement, notice and evidence coverage across the portfolio.']};
    return `${head('Reports and insights','Practical management reports generated from your properties, leases, payments, municipal bills and operations.',`<button class="secondary" data-action="export-report">Export current report CSV</button><button class="primary" data-action="backup">Download full backup</button>`)}<div class="report-grid">${Object.entries(definitions).map(([key,[name,desc]])=>`<article class="report-card"><h3>${name}</h3><p>${desc}</p><button class="${r===key?'primary':'secondary'}" data-report="${key}">${r===key?'Viewing report':'Open report'}</button></article>`).join('')}</div>${renderReportDetail(r)}`;
  }
  function renderReportDetail(type) {
    const due=monthlyDue(), paid=monthPayments(), arr=Math.max(0,due-paid); let title='', headers=[], rows=[];
    if(type==='executive'){title='Executive portfolio summary';headers=['Measure','Value','Management meaning'];rows=[['Properties',state.properties.length,'Managed portfolio records'],['Units',state.units.length,`${occupancy().rate}% occupancy`],['Active monthly rent',money(due),'Contracted recurring revenue'],['Payments this month',money(paid),'Recorded collections'],['Open billed balance',money(openChargeBalance()),'Recorded charges less allocated payments'],['Municipal exposure',money(municipalOwing()),'Current tracked operating-cost balance'],['Open exceptions',complianceIssues().length,'Items requiring review/action']];}
    if(type==='finance'){title='Collections, charges and arrears';headers=['Lease / tenant','Open charges','Payments recorded','Open billed balance'];rows=getActiveLeases().map(l=>{const open=openCharges().filter(c=>c.leaseId===l.id).reduce((s,c)=>s+chargeBalance(c),0);const got=state.payments.filter(p=>p.leaseId===l.id).reduce((s,p)=>s+Number(p.amount),0);return [leaseName(l.id),money(state.invoices.filter(c=>c.leaseId===l.id).reduce((s,c)=>s+Number(c.amount||0),0)),money(got),money(open)];});}
    if(type==='leases'){title='Lease expiry and renewal pipeline';headers=['Lease / tenant','Expiry','Days remaining','Renewal stage'];rows=getActiveLeases().map(l=>[leaseName(l.id),dateLabel(l.endDate),l.endDate?diffDays(l.endDate):'Not recorded',state.renewals.find(r=>r.leaseId===l.id)?.stage||'No renewal case']).sort((a,b)=>String(a[1]).localeCompare(String(b[1])));}
    if(type==='vacancy'){title='Vacancy and prospect pipeline';headers=['Property / unit','Market rent','Listing status','Interested prospects','Next follow-up'];rows=state.units.filter(u=>u.status==='Vacant').map(u=>{const listing=state.listings.find(x=>x.unitId===u.id);const ps=state.prospects.filter(p=>p.unitId===u.id||(!p.unitId&&p.propertyId===u.propertyId));return [`${propertyName(u.propertyId)} · ${u.name}`,money(u.marketRent),listing?.status||'Not listed',ps.length,ps.map(p=>p.followUpDate).filter(Boolean).sort()[0]||'—'];});}
    if(type==='operations'){title='Operations performance';headers=['Activity','Property','Due / date','Cost / status'];rows=[...state.workOrders.map(w=>[`Work order: ${w.title}`,propertyName(w.propertyId),dateLabel(w.dueDate),`${money(w.actualCost||0)} actual · ${w.priority} · ${w.status}`]),...state.inspections.map(i=>[`Inspection: ${i.type}`,propertyName(i.propertyId),dateLabel(i.date),`${i.conditionScore||'—'}/5 · ${i.status}`])];}
    if(type==='compliance'){title='Compliance exception register';headers=['Control area','Record','Exception','Priority'];rows=complianceIssues().map(i=>[i.kind,i.name,i.detail,i.level==='red'?'Action required':'Review']);}
    if(type==='municipal'){title='Municipal exposure by property';headers=['Property','Account no.','Due date','Balance','Status'];rows=state.municipalAccounts.map(m=>[propertyName(m.propertyId),m.accountNo||'—',dateLabel(m.dueDate),money(m.balance),m.dueDate&&diffDays(m.dueDate)<0&&Number(m.balance)>0?'Overdue':'Current']);}
    if(type==='documents'){title='Document control coverage';headers=['Document','Type','Lease / property','Status','Review date'];rows=state.documents.map(d=>[d.name,d.type,`${leaseName(d.leaseId)} · ${propertyName(d.propertyId)}`,d.status||'Current',dateLabel(d.expiryDate)]);}
    const totals=type==='finance'?`Expected ${money(due)} · Payments this month ${money(paid)} · Open billed balance ${money(openChargeBalance())} · Estimate gap ${money(arr)}`:`${rows.length} record(s) in this report`;
    return `<section class="panel"><div class="panel-head"><div><h3>${title}</h3><span class="sub">${totals}</span></div><span>${new Intl.DateTimeFormat('en-NA',{month:'short',year:'numeric'}).format(new Date())}</span></div><div class="table-wrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((cell,i)=>`<td class="${i===0?'main':''}">${esc(cell)}</td>`).join('')}</tr>`).join('')||noRows(headers.length,'There are no records available for this report.')}</tbody></table></div></section>`;
  }
  function renderAdmin() { const members=state.teamMembers.map(m=>`<tr><td class="main">${esc(m.name)}</td><td>${esc(m.role)}</td><td>${esc(m.email||'—')}</td><td>${esc(m.status||'Invited')}</td><td><button class="link-button" data-action="form" data-type="member" data-id="${m.id}">Edit</button></td></tr>`).join(''); return `${head('Administration','Protect the workspace, migrate V1–V9 records, prepare roles and maintain an exportable audit trail.',`<button class="primary" data-action="backup">Download full backup</button>`)}<div class="grid equal"><section class="panel"><div class="panel-head"><h3>Workspace controls</h3></div><div class="panel-body"><div class="status-bar">This local V10 workspace preserves V1–V9 workflows. Its free Supabase backup is private to the signed-in user; the supplied relational schema is the scale-up foundation for staff roles and APIs.</div><div class="view-actions"><button class="secondary" data-action="cloud-signin">Sign in</button><button class="secondary" data-action="cloud-signup">Create account</button><button class="primary" data-action="cloud-save">Save to cloud</button><button class="secondary" data-action="cloud-load">Load cloud backup</button><button class="secondary" data-action="cloud-signout">Sign out</button><button class="secondary" data-action="import">Import V10 backup</button><button class="secondary" data-action="migrate">Run legacy migration</button><button class="danger" data-action="reset">Reset V10 local data</button></div></div></section><section class="panel"><div class="panel-head"><h3>Data controls</h3></div><div class="panel-body"><div class="list-kpi"><span>Last audit event</span><strong>${state.audit[0]?dateLabel(state.audit[0].at.slice(0,10)):'—'}</strong></div><div class="list-kpi"><span>Stored audit events</span><strong>${state.audit.length}</strong></div><div class="list-kpi"><span>V1–V9 source data retained</span><strong>Yes</strong></div><div class="list-kpi"><span>Cloud model</span><strong>Private backup + relational scale-up</strong></div></div></section></div><section class="panel" style="margin-top:18px"><div class="panel-head"><h3>Team role design</h3><button class="secondary" data-action="form" data-type="member">Add team member</button></div><div class="panel-body"><p class="sub">Roles are staged here for the cloud release: Administrator, Property Manager, Finance, Operations, Legal and Viewer. They become enforced by Supabase Row Level Security after the relational connection is enabled.</p></div><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Role</th><th>Email</th><th>Status</th><th></th></tr></thead><tbody>${members||noRows(5,'Add your first role assignment when preparing staff access.')}</tbody></table></div></section><section class="panel" style="margin-top:18px"><div class="panel-head"><h3>Recent audit activity</h3></div><div class="table-wrap"><table class="table"><thead><tr><th>When</th><th>Action</th><th>Detail</th></tr></thead><tbody>${state.audit.slice(0,25).map(a=>`<tr><td>${new Date(a.at).toLocaleString('en-NA')}</td><td class="main">${esc(a.action)}</td><td>${esc(a.detail)}</td></tr>`).join('')||noRows(3,'Actions will appear here as records are added or changed.')}</tbody></table></div></section>`; }

  function formHtml(type, record={}, extra={}) {
    const propertyOptions = state.properties.map(p=>({value:p.id,label:propertyName(p.id)}));
    const unitOptions = state.units.map(u=>({value:u.id,label:`${propertyName(u.propertyId)} · ${u.name}`}));
    const leaseOptions = state.leases.map(l=>({value:l.id,label:leaseName(l.id)}));
    const input=(name,label,value='',type='text',help='')=>`<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${esc(value)}">${help?`<p class="form-help">${help}</p>`:''}</div>`;
    const select=(name,label,value,options)=>`<div class="field"><label>${label}</label><select name="${name}">${options.map(o=>{const item=typeof o==='object'?o:{value:o,label:o};return `<option value="${esc(item.value)}" ${String(item.value)===String(value)?'selected':''}>${esc(item.label)}</option>`;}).join('')}</select></div>`;
    const optionalSelect=(name,label,value,options,placeholder='Not selected')=>`<div class="field"><label>${label}</label><select name="${name}"><option value="">${esc(placeholder)}</option>${options.map(o=>{const item=typeof o==='object'?o:{value:o,label:o};return `<option value="${esc(item.value)}" ${String(item.value)===String(value)?'selected':''}>${esc(item.label)}</option>`;}).join('')}</select></div>`;
    if(type==='property') return `<div class="form-grid">${input('code','Property / ERF code',record.code||'')}${input('name','Property name',record.name||'')}${input('address','Address',record.address||'')}${select('type','Property type',record.type||'Residential',['Residential','Commercial','Mixed Use','Industrial','Land'])}${select('status','Status',record.status||'Active',['Active','Inactive','Archived'])}${input('erf','ERF / title reference',record.erf||'')}</div>`;
    if(type==='unit') return `<div class="form-grid">${select('propertyId','Property',record.propertyId||extra.propertyId||'',propertyOptions)}${input('name','Unit / rental area',record.name||'')}${select('type','Unit type',record.type||'Rental Unit',['Rental Unit','Office','Shop','Warehouse','Common Area','Land'])}${select('status','Occupancy status',record.status||'Vacant',['Vacant','Occupied','Unavailable','Under maintenance'])}${input('marketRent','Monthly market rent',record.marketRent||'', 'number')}</div>`;
    if(type==='owner') return `<div class="form-grid">${input('name','Owner legal name',record.name||'')}${input('phone','Phone / WhatsApp',record.phone||'')}${input('email','Email',record.email||'','email')}${optionalSelect('propertyId','Primary property',record.propertyId||'',propertyOptions,'Portfolio owner')}${input('managementFeePct','Management fee %',record.managementFeePct||'', 'number')}${select('status','Status',record.status||'Active',['Active','Inactive'])}<div class="field span2"><label>Owner notes</label><textarea name="notes">${esc(record.notes||'')}</textarea></div></div>`;
    if(type==='prospect') return `<div class="form-grid">${input('name','Prospect name',record.name||'')}${input('phone','Phone / WhatsApp',record.phone||'')}${input('email','Email',record.email||'','email')}${optionalSelect('propertyId','Interested property',record.propertyId||'',propertyOptions,'Any property')}${optionalSelect('unitId','Interested unit',record.unitId||'',unitOptions,'Any suitable unit')}${select('stage','Pipeline stage',record.stage||'Lead',['Lead','Viewing scheduled','Application received','Screening','Approved','Leased','Declined'])}${input('followUpDate','Follow-up date',record.followUpDate||'','date')}<div class="field span2"><label>Requirements / notes</label><textarea name="notes">${esc(record.notes||'')}</textarea></div></div>`;
    if(type==='listing') return `<div class="form-grid">${select('unitId','Vacant unit',record.unitId||extra.unitId||'',unitOptions)}${input('availableDate','Available from',record.availableDate||today(),'date')}${input('askingRent','Advertised monthly rent',record.askingRent||'', 'number')}${select('status','Listing status',record.status||'Available',['Draft','Available','On hold','Let'])}${input('title','Marketing title',record.title||'')}<div class="field span2"><label>Listing / viewing notes</label><textarea name="notes">${esc(record.notes||'')}</textarea></div></div>`;
    if(type==='lease') return `<div class="form-grid">${input('leaseNo','Lease / agreement reference',record.leaseNo||'')}${input('tenantName','Tenant legal name',contact(record.contactId)?.name||'')}${input('tenantPhone','Tenant WhatsApp/contact number',contact(record.contactId)?.phone||'')}${select('propertyId','Property',record.propertyId||'',propertyOptions)}${select('unitId','Unit / rental area',record.unitId||'',unitOptions)}${input('startDate','Lease start date',record.startDate||'','date')}${input('endDate','Lease expiry date',record.endDate||'','date')}${input('monthlyRent','Monthly contractual rent',record.monthlyRent||'','number')}${input('escalation','Annual escalation %',record.escalation||0,'number')}${input('deposit','Deposit held',record.deposit||0,'number')}${input('noticeDays','Notice period (days)',record.noticeDays||60,'number')}${select('status','Lease status',record.status||'Draft',['Draft','Active','Signed','Renewal in progress','Terminated'])}<div class="field span2"><label>Agreement status / notes</label><textarea name="notes">${esc(record.notes||'')}</textarea></div></div>`;
    if(type==='payment') return `<div class="form-grid">${select('leaseId','Lease / tenant',record.leaseId||'',leaseOptions)}${optionalSelect('chargeId','Allocate to open charge',record.chargeId||'',openCharges().map(c=>({value:c.id,label:`${leaseName(c.leaseId)} · ${c.description||c.type||'Charge'} · ${money(chargeBalance(c))}`})),'Leave unallocated')}${input('receiptNo','Receipt number',record.receiptNo||`MBM-${today().replaceAll('-','')}-${String(state.payments.length+1).padStart(3,'0')}`)}${input('paymentDate','Payment date',record.paymentDate||today(),'date')}${input('period','Rental period',record.period||new Intl.DateTimeFormat('en-NA',{month:'long',year:'numeric'}).format(new Date()))}${input('amount','Amount received',record.amount||'','number')}${select('method','Payment method',record.method||'EFT',['EFT','Cash','Card','Bank deposit','Other'])}<div class="field span2"><label>Receipt notes</label><textarea name="notes">${esc(record.notes||'')}</textarea></div></div>`;
    if(type==='charge') return `<div class="form-grid">${select('leaseId','Lease / tenant',record.leaseId||'',leaseOptions)}${select('type','Charge type',record.type||'Rent',['Rent','Utilities','Deposit','Late fee','Maintenance recovery','Other'])}${input('chargeDate','Charge date',record.chargeDate||today(),'date')}${input('dueDate','Due date',record.dueDate||today(),'date')}${input('description','Charge description',record.description||'Monthly rent')}${input('amount','Amount',record.amount||'', 'number')}<div class="field span2"><label>Note</label><textarea name="notes">${esc(record.notes||'')}</textarea></div></div>`;
    if(type==='municipal') return `<div class="form-grid">${select('propertyId','Property',record.propertyId||'',propertyOptions)}${input('accountNo','Municipal account number',record.accountNo||'')}${input('balance','Current amount owing',record.balance||'','number')}${input('statementDate','Statement date',record.statementDate||'','date')}${input('dueDate','Due date',record.dueDate||'','date')}<div class="field span2"><label>Reference / notes</label><textarea name="notes">${esc(record.notes||'')}</textarea></div></div>`;
    if(type==='municipal-payment') return `<div class="form-grid">${input('paymentDate','Payment date',today(),'date')}${input('amount','Amount paid','', 'number')}${input('reference','Payment reference','')}${input('method','Method','EFT')}<div class="field span2"><label>Notes</label><textarea name="notes"></textarea></div></div>`;
    if(type==='renewal') return `<div class="form-grid">${select('leaseId','Lease contract',record.leaseId||'',getActiveLeases().map(l=>({value:l.id,label:leaseName(l.id)})))}${select('stage','Pipeline stage',record.stage||'Expiry review',['Expiry review','Notice issued','Terms negotiation','Legal review','Management approval','Awaiting signature','Renewed / billing activated','Non-renewal / exit'])}${input('nextActionDate','Next action due',record.nextActionDate||'','date')}${input('noticeDate','Formal notice date',record.noticeDate||'','date')}${input('termMonths','Proposed term (months)',record.termMonths||12,'number')}${input('proposedRent','Proposed monthly rent',record.proposedRent||'','number')}${select('legalStatus','Legal review',record.legalStatus||'Not started',['Not started','In review','Changes requested','Approved by legal'])}${select('approvalStatus','Management approval',record.approvalStatus||'Not requested',['Not requested','Pending approval','Approved','Rejected'])}${input('agreementRef','New agreement reference',record.agreementRef||'')}${input('signatureDate','Signature date',record.signatureDate||'','date')}${input('billingDate','Billing activation date',record.billingDate||'','date')}<div class="field span2"><label>Negotiation / legal notes</label><textarea name="notes">${esc(record.notes||'')}</textarea></div></div>`;
    if(type==='vendor') return `<div class="form-grid">${input('name','Supplier / vendor name',record.name||'')}${select('trade','Trade / service',record.trade||'Plumbing',['Plumbing','Electrical','Building repair','Security','Cleaning','Legal','Other'])}${input('phone','Phone / WhatsApp',record.phone||'')}${input('email','Email',record.email||'','email')}${select('status','Status',record.status||'Active',['Active','Preferred','Inactive'])}<div class="field span2"><label>Supplier notes / rate card</label><textarea name="notes">${esc(record.notes||'')}</textarea></div></div>`;
    if(type==='work') return `<div class="form-grid">${select('propertyId','Property',record.propertyId||'',propertyOptions)}${input('unitName','Unit / area',record.unitName||'')}${input('title','Work order title',record.title||'')}${select('category','Category',record.category||'Building repair',['Plumbing','Electrical','Building repair','Security','Cleaning','Other'])}${select('priority','Priority',record.priority||'Normal',['Normal','High','Urgent'])}${optionalSelect('vendorId','Approved supplier',record.vendorId||'',state.vendors.map(v=>({value:v.id,label:`${v.name} · ${v.trade||'General'}`})),'Assign later')}${input('assignee','Assigned staff / alternative',record.assignee||'')}${input('dueDate','Due date',record.dueDate||'','date')}${input('quotedAmount','Approved quote amount',record.quotedAmount||'', 'number')}${input('actualCost','Actual cost',record.actualCost||'', 'number')}<div class="field span2"><label>Description / required outcome</label><textarea name="notes">${esc(record.notes||'')}</textarea></div></div>`;
    if(type==='inspection') return `<div class="form-grid">${select('propertyId','Property',record.propertyId||'',propertyOptions)}${input('unitName','Unit / area',record.unitName||'')}${select('type','Inspection type',record.type||'Routine inspection',['Routine inspection','Move-in inspection','Move-out inspection','Safety inspection','Unit turn inspection'])}${input('date','Scheduled date',record.date||'','date')}${input('inspector','Inspector',record.inspector||'')}${select('conditionScore','Condition score (1–5)',record.conditionScore||'',['','1','2','3','4','5'])}${input('followUpDue','Defect follow-up due',record.followUpDue||'','date')}<div class="field span2"><label>Defects / required repair</label><textarea name="defects">${esc(record.defects||'')}</textarea></div><div class="field span2"><label>Scope / evidence notes</label><textarea name="notes">${esc(record.notes||'')}</textarea></div></div>`;
    if(type==='document') return `<div class="form-grid">${optionalSelect('leaseId','Related lease',record.leaseId||extra.leaseId||'',leaseOptions,'No lease link')}${optionalSelect('propertyId','Related property',record.propertyId||'',propertyOptions,'No property link')}${input('name','Document file/name',record.name||'')}${select('type','Document type',record.type||'Lease document',['Lease document','Lease amendment','Notice','Municipal statement','Inspection evidence','Vendor quote','Approval','Other'])}${select('status','Document status',record.status||'Current',['Draft','Current','Superseded','Legacy reference'])}${input('expiryDate','Document expiry/review date',record.expiryDate||'','date')}<div class="field"><label>Private file upload (optional)</label><input name="file" type="file" accept=".pdf,.doc,.docx,.png,.jpg,.jpeg"></div>${input('storagePath','Existing private storage path',record.storagePath||'')}<div class="field span2"><label>Reference / notes</label><textarea name="notes">${esc(record.notes||'')}</textarea></div></div>`;
    if(type==='task') return `<div class="form-grid">${input('title','Task title',record.title||'')}${input('date','Due date',record.date||today(),'date')}${select('priority','Priority',record.priority||'Normal',['Normal','High','Urgent'])}${input('owner','Owner',record.owner||'')}<div class="field span2"><label>Notes</label><textarea name="notes">${esc(record.notes||'')}</textarea></div></div>`;
    if(type==='event') return `<div class="form-grid">${input('title','Property event title',record.title||'')}${input('date','Event date',record.date||today(),'date')}${select('type','Event type',record.type||'Management meeting',['Management meeting','Vendor appointment','Property viewing','Payment follow-up','Other property event'])}${optionalSelect('propertyId','Property (optional)',record.propertyId||'',propertyOptions,'Portfolio-wide event')}<div class="field span2"><label>Notes</label><textarea name="notes">${esc(record.notes||'')}</textarea></div></div>`;
    if(type==='member') return `<div class="form-grid">${input('name','Team member name',record.name||'')}${input('email','Email',record.email||'','email')}${select('role','Role',record.role||'Property Manager',['Administrator','Property Manager','Finance','Operations','Legal','Viewer'])}${select('status','Status',record.status||'Invited',['Invited','Active','Inactive'])}<div class="field span2"><label>Notes</label><textarea name="notes">${esc(record.notes||'')}</textarea></div></div>`;
    return '';
  }
  function openForm(type, id, extra={}) { const group={property:'properties',unit:'units',owner:'owners',prospect:'prospects',listing:'listings',lease:'leases',payment:'payments',charge:'invoices',municipal:'municipalAccounts','municipal-payment':'municipalAccounts',renewal:'renewals',vendor:'vendors',work:'workOrders',inspection:'inspections',document:'documents',task:'tasks',event:'calendarEvents',member:'teamMembers'}[type];const record=id&&group?state[group].find(x=>x.id===id):{};$('#modalEyebrow').textContent=type.toUpperCase();$('#modalTitle').textContent=`${(id&&type!=='municipal-payment')?'Edit':'Add'} ${({property:'property',unit:'unit',owner:'owner',prospect:'prospect',listing:'vacancy listing',lease:'lease & contract',payment:'payment receipt',charge:'finance charge',municipal:'municipal account','municipal-payment':'municipal payment',renewal:'renewal case',vendor:'supplier',work:'work order',inspection:'inspection',document:'document record',task:'management task',event:'property event',member:'team member'})[type]}`;$('#modalBody').innerHTML=formHtml(type,record,extra);$('#modalForm').dataset.type=type;$('#modalForm').dataset.id=id||'';$('#modal').showModal(); }
  function fields(form) { return Object.fromEntries(new FormData(form).entries()); }
  function addOrUpdate(group, item, id) { if(id){const i=state[group].findIndex(x=>x.id===id);state[group][i]={...state[group][i],...item,updatedAt:today()};return state[group][i];} const saved={id:uid(group.slice(0,-1)),...item,createdAt:today()};state[group].push(saved);return saved; }
  async function saveForm(e) { e.preventDefault(); const form=$('#modalForm'), type=form.dataset.type, id=form.dataset.id, data=fields(form); let saved;
    if(type==='property'){ if(!data.code||!data.name) return alert('Enter the property/ERF code and property name.');saved=addOrUpdate('properties',data,id);audit(state,id?'Property updated':'Property created',propertyName(saved.id)); }
    if(type==='unit'){if(!data.propertyId||!data.name)return alert('Select a property and enter the unit/rental area.');data.marketRent=Number(data.marketRent||0);saved=addOrUpdate('units',data,id);audit(state,id?'Unit updated':'Unit created',`${propertyName(saved.propertyId)} · ${saved.name}`);}
    if(type==='owner'){if(!data.name)return alert('Enter the owner name.');data.managementFeePct=Number(data.managementFeePct||0);saved=addOrUpdate('owners',data,id);audit(state,id?'Owner updated':'Owner added',saved.name);}
    if(type==='prospect'){if(!data.name)return alert('Enter the prospect name.');saved=addOrUpdate('prospects',data,id);audit(state,id?'Prospect updated':'Prospect added',saved.name);}
    if(type==='listing'){if(!data.unitId)return alert('Select a vacant unit.');data.askingRent=Number(data.askingRent||0);saved=addOrUpdate('listings',data,id);audit(state,id?'Vacancy listing updated':'Vacancy listing created',unit(saved.unitId)?.name||'Unit');}
    if(type==='lease'){if(!data.tenantName||!data.propertyId||!data.unitId||!data.leaseNo)return alert('Enter tenant, property, unit and lease reference.');let c=id?contact(lease(id).contactId):null;if(c){c.name=data.tenantName;c.phone=data.tenantPhone;}else{c={id:uid('contact'),name:data.tenantName,phone:data.tenantPhone,email:'',kind:'Tenant',createdAt:today()};state.contacts.push(c);}data.contactId=c.id;delete data.tenantName;delete data.tenantPhone;['monthlyRent','escalation','deposit','noticeDays'].forEach(k=>data[k]=Number(data[k]||0));saved=addOrUpdate('leases',data,id);const u=unit(saved.unitId);if(u)u.status=activeStatus(saved.status)?'Occupied':u.status;audit(state,id?'Lease updated':'Lease created',leaseName(saved.id));}
    if(type==='payment'){if(!data.leaseId||!data.amount)return alert('Select the lease and enter the received amount.');data.amount=Number(data.amount);data.propertyId=lease(data.leaseId)?.propertyId||'';if(data.chargeId){const c=state.invoices.find(x=>x.id===data.chargeId);if(!c||c.leaseId!==data.leaseId)return alert('The selected charge must belong to the payment lease.');if(data.amount>chargeBalance(c)+.009)return alert(`The payment exceeds the selected charge balance of ${money(chargeBalance(c))}. Leave it unallocated or record a separate charge.`);}saved=addOrUpdate('payments',data,id);if(data.chargeId){const old=state.allocations.find(a=>a.paymentId===saved.id&&a.chargeId===data.chargeId);if(old)old.amount=saved.amount;else state.allocations.push({id:uid('allocation'),paymentId:saved.id,chargeId:data.chargeId,amount:saved.amount,createdAt:today()});}audit(state,id?'Payment updated':'Payment recorded',`${saved.receiptNo} · ${money(saved.amount)}`);}
    if(type==='charge'){if(!data.leaseId||!data.amount)return alert('Select a lease and enter the charge amount.');data.amount=Number(data.amount);data.propertyId=lease(data.leaseId)?.propertyId||'';data.status='Open';saved=addOrUpdate('invoices',data,id);audit(state,id?'Finance charge updated':'Finance charge recorded',`${leaseName(data.leaseId)} · ${money(data.amount)}`);}
    if(type==='municipal'){if(!data.propertyId||!data.balance)return alert('Select property and enter balance.');data.balance=Number(data.balance);const existing=state.municipalAccounts.find(m=>m.propertyId===data.propertyId&&m.id!==id);saved=addOrUpdate('municipalAccounts',data,id||existing?.id);audit(state,'Municipal account saved',`${propertyName(data.propertyId)} · ${money(data.balance)}`);}
    if(type==='municipal-payment'){const account=state.municipalAccounts.find(m=>m.id===id);if(!account||!data.amount)return alert('Enter the amount paid.');data.amount=Number(data.amount);if(data.amount>Number(account.balance||0)+.009)return alert(`Payment is greater than the current account balance of ${money(account.balance)}.`);account.balance=Math.max(0,Number(account.balance||0)-data.amount);state.municipalPayments.push({id:uid('municipalPayment'),accountId:account.id,propertyId:account.propertyId,...data,createdAt:today()});audit(state,'Municipal payment recorded',`${propertyName(account.propertyId)} · ${money(data.amount)}`);}
    if(type==='renewal'){if(!data.leaseId)return alert('Select the lease contract.');['termMonths','proposedRent'].forEach(k=>data[k]=Number(data[k]||0));saved=addOrUpdate('renewals',data,id);if(data.stage==='Renewed / billing activated'){const l=lease(data.leaseId);if(!['Approved by legal'].includes(data.legalStatus)||data.approvalStatus!=='Approved'||!data.agreementRef||!data.signatureDate||!data.billingDate||!data.proposedRent||!data.termMonths){return alert('Renewal activation requires legal approval, management approval, agreement reference, signature date, billing activation date, term and proposed rent.');}const end=new Date(`${l.endDate||today()}T00:00:00`);l.startDate=data.billingDate;l.endDate=new Date(end.setMonth(end.getMonth()+Number(data.termMonths))).toISOString().slice(0,10);l.monthlyRent=Number(data.proposedRent);l.leaseNo=data.agreementRef;l.status='Active';}audit(state,id?'Renewal updated':'Renewal case created',leaseName(data.leaseId));}
    if(type==='vendor'){if(!data.name)return alert('Enter the supplier name.');saved=addOrUpdate('vendors',data,id);audit(state,id?'Supplier updated':'Supplier added',saved.name);}
    if(type==='work'){if(!data.propertyId||!data.title)return alert('Select a property and enter a work order title.');['quotedAmount','actualCost'].forEach(k=>data[k]=Number(data[k]||0));data.status=id?state.workOrders.find(x=>x.id===id).status:'Open';saved=addOrUpdate('workOrders',data,id);audit(state,id?'Work order updated':'Work order created',data.title);}
    if(type==='inspection'){if(!data.propertyId||!data.date)return alert('Select a property and date.');data.status=id?state.inspections.find(x=>x.id===id).status:'Scheduled';saved=addOrUpdate('inspections',data,id);audit(state,id?'Inspection updated':'Inspection scheduled',data.type);}
    if(type==='document'){const file=form.querySelector('input[name="file"]')?.files?.[0];delete data.file;if(file){const linkedLease=lease(data.leaseId);const result=await window.MBMCloudV10?.uploadPrivateDocument?.(file,{leaseNo:linkedLease?.leaseNo,propertyCode:property(data.propertyId||linkedLease?.propertyId)?.code});if(!result?.ok)return alert(`Private upload failed: ${result?.message||'Sign in to Supabase first.'}`);data.storagePath=result.path;if(!data.name)data.name=file.name;}if(!data.name)return alert('Enter a document file/name or choose a file.');saved=addOrUpdate('documents',data,id);audit(state,id?'Document record updated':'Document registered',data.name);}
    if(type==='task'){if(!data.title||!data.date)return alert('Enter a task and due date.');data.status=id?state.tasks.find(x=>x.id===id).status:'Open';saved=addOrUpdate('tasks',data,id);audit(state,id?'Task updated':'Task added',data.title);}
    if(type==='event'){if(!data.title||!data.date)return alert('Enter the event title and date.');saved=addOrUpdate('calendarEvents',data,id);audit(state,id?'Property event updated':'Property event added',data.title);}
    if(type==='member'){if(!data.name||!data.role)return alert('Enter the team member and role.');saved=addOrUpdate('teamMembers',data,id);audit(state,id?'Team role updated':'Team role staged',`${data.name} · ${data.role}`);}
    save('Saved');$('#modal').close();render();
  }
  function printReceipt(id) { const p=state.payments.find(x=>x.id===id);if(!p)return;const l=lease(p.leaseId),c=contact(l?.contactId),u=unit(l?.unitId);const win=window.open('','_blank');win.document.write(`<!doctype html><title>Receipt ${esc(p.receiptNo)}</title><style>body{font-family:Arial;padding:35px;color:#12395f}h1{font-size:24px}table{border-collapse:collapse;width:100%;margin-top:20px}td,th{padding:10px;border:1px solid #ddd;text-align:left}.total{font-size:21px;font-weight:bold}</style><h1>Musa Business Management CC</h1><p>Rent payment receipt</p><table><tr><th>Receipt no.</th><td>${esc(p.receiptNo)}</td></tr><tr><th>Date</th><td>${dateLabel(p.paymentDate)}</td></tr><tr><th>Tenant</th><td>${esc(c?.name||'')}</td></tr><tr><th>Property / unit</th><td>${esc(propertyName(l?.propertyId))} · ${esc(u?.name||'')}</td></tr><tr><th>Rental period</th><td>${esc(p.period||'')}</td></tr><tr><th>Method</th><td>${esc(p.method||'')}</td></tr></table><p class="total">Amount received: ${money(p.amount)}</p><p>${esc(p.notes||'')}</p>`);win.document.close();win.print(); }
  function whatsapp(id) { const p=state.payments.find(x=>x.id===id),l=lease(p?.leaseId),c=contact(l?.contactId);if(!p||!c?.phone)return alert('A tenant contact number is required before opening WhatsApp.');const number=String(c.phone).replace(/\D/g,'').replace(/^0/,'264');const message=`Hello ${c.name}, MBM confirms receipt ${p.receiptNo} for ${money(p.amount)} on ${dateLabel(p.paymentDate)}. Rental period: ${p.period||'—'}. Thank you.`;window.open(`https://wa.me/${number}?text=${encodeURIComponent(message)}`,'_blank','noopener');}
  function renewalWhatsapp(id) { const r=state.renewals.find(x=>x.id===id),l=lease(r?.leaseId),c=contact(l?.contactId);if(!r||!c?.phone)return alert('A tenant contact number is required before opening WhatsApp.');const number=String(c.phone).replace(/\D/g,'').replace(/^0/,'264');const message=`Hello ${c.name}, MBM renewal update for ${l?.leaseNo||'your lease'}: stage ${r.stage}. Current contract expiry: ${dateLabel(l?.endDate)}. Next action: ${dateLabel(r.nextActionDate)}. Please contact MBM if you have questions.`;window.open(`https://wa.me/${number}?text=${encodeURIComponent(message)}`,'_blank','noopener');audit(state,'Renewal WhatsApp prepared',`${leaseName(r.leaseId)} · ${r.stage}`);save('Renewal update prepared');}
  function download(name, text, type='application/json') { const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000); }
  function exportCalendar(){const ics=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//MBM//Property Manager//EN'];eventItems().forEach((e,i)=>{if(!e.date)return;ics.push('BEGIN:VEVENT',`UID:mbm-${i}-${e.date}@mbm`,`DTSTAMP:${today().replaceAll('-','')}T000000Z`,`DTSTART;VALUE=DATE:${e.date.replaceAll('-','')}`,`SUMMARY:${String(e.label).replace(/[,;\n]/g,' ')}`,`DESCRIPTION:${String(e.kind).replace(/[,;\n]/g,' ')}`,'END:VEVENT');});ics.push('END:VCALENDAR');download(`MBM-calendar-${today()}.ics`,ics.join('\r\n'),'text/calendar;charset=utf-8');audit(state,'Calendar exported','ICS calendar file created.');save('Calendar exported');}
  function exportMunicipal(){const rows=[['Property','Account number','Statement date','Due date','Balance'],...state.municipalAccounts.map(m=>[propertyName(m.propertyId),m.accountNo||'',m.statementDate||'',m.dueDate||'',m.balance||0])];download(`MBM-municipal-register-${today()}.csv`,rows.map(r=>r.map(x=>`"${String(x??'').replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv');}
  function parseCsvLine(line){const cells=[];let current='',quoted=false;for(let i=0;i<line.length;i++){const char=line[i];if(char==='"'){if(quoted&&line[i+1]==='"'){current+='"';i++;}else quoted=!quoted;}else if(char===','&&!quoted){cells.push(current.trim());current='';}else current+=char;}cells.push(current.trim());return cells;}
  function importHistory(file){const reader=new FileReader();reader.onload=()=>{try{let records=[];const raw=String(reader.result||'').trim();if(file.name.toLowerCase().endsWith('.json'))records=JSON.parse(raw);else{const lines=raw.split(/\r?\n/).filter(Boolean);const headers=parseCsvLine(lines.shift()).map(h=>h.trim().toLowerCase().replace(/\s+/g,'_'));records=lines.map(line=>Object.fromEntries(parseCsvLine(line).map((v,i)=>[headers[i],v])));}if(!Array.isArray(records))throw new Error('The file must contain an array or a CSV with headings.');let added=0,skipped=0;records.forEach((r,index)=>{const receiptNo=r.receipt_no||r.receiptNo||r.receiptnumber||`IMPORT-${today().replaceAll('-','')}-${index+1}`;if(state.payments.some(p=>p.receiptNo===receiptNo)){skipped++;return;}const tenant=String(r.tenant||r.tenant_name||r.customer||'').trim();const unitName=String(r.unit||r.unit_name||'').trim();const l=state.leases.find(x=>contact(x.contactId)?.name===tenant&&(!unitName||unit(x.unitId)?.name===unitName));const amount=Number(r.amount||r.net||r.total||0);if(!amount){skipped++;return;}state.payments.push({id:uid('payment'),receiptNo,leaseId:l?.id||'',propertyId:l?.propertyId||'',paymentDate:r.receipt_date||r.paymentDate||today(),period:[r.month,r.year].filter(Boolean).join(' ')||r.period||'',amount,method:r.payment_method||r.method||'Historical import',notes:r.notes||'',createdAt:today()});added++;});audit(state,'Historical payments imported',`${added} added; ${skipped} skipped or duplicate.`);save('Historical payments imported');render();alert(`${added} payment(s) imported. ${skipped} row(s) skipped.`);}catch(err){alert(`Import failed: ${err.message}`);}};reader.readAsText(file);}
  function exportReport(){const report=state.ui.report||'executive';const rows=[['MBM Property Management Report',report],['Generated',new Date().toLocaleString('en-NA')],[]];if(report==='finance'){rows.push(['Lease/Tenant','Total charges','Payments','Open billed balance']);getActiveLeases().forEach(l=>rows.push([leaseName(l.id),state.invoices.filter(c=>c.leaseId===l.id).reduce((s,c)=>s+Number(c.amount||0),0),state.payments.filter(p=>p.leaseId===l.id).reduce((s,p)=>s+Number(p.amount||0),0),openCharges().filter(c=>c.leaseId===l.id).reduce((s,c)=>s+chargeBalance(c),0)]));}else if(report==='municipal'){rows.push(['Property','Account','Due date','Balance']);state.municipalAccounts.forEach(m=>rows.push([propertyName(m.propertyId),m.accountNo,m.dueDate,m.balance]));}else if(report==='leases'){rows.push(['Lease','Expiry','Days remaining','Renewal stage']);getActiveLeases().forEach(l=>rows.push([leaseName(l.id),l.endDate,diffDays(l.endDate),state.renewals.find(r=>r.leaseId===l.id)?.stage||'No renewal case']));}else if(report==='vacancy'){rows.push(['Property','Unit','Market rent','Listing','Prospects']);state.units.filter(u=>u.status==='Vacant').forEach(u=>{const listing=state.listings.find(x=>x.unitId===u.id);rows.push([propertyName(u.propertyId),u.name,u.marketRent,listing?.status||'Not listed',state.prospects.filter(p=>p.unitId===u.id||(!p.unitId&&p.propertyId===u.propertyId)).length]);});}else if(report==='operations'){rows.push(['Activity','Property','Due','Vendor','Quoted','Actual','Status']);state.workOrders.forEach(w=>rows.push([w.title,propertyName(w.propertyId),w.dueDate,vendor(w.vendorId)?.name||w.assignee||'',w.quotedAmount||0,w.actualCost||0,w.status]));state.inspections.forEach(i=>rows.push([i.type,propertyName(i.propertyId),i.date,i.inspector||'','','',i.status]));}else if(report==='compliance'){rows.push(['Control','Record','Exception','Priority']);complianceIssues().forEach(i=>rows.push([i.kind,i.name,i.detail,i.level]));}else if(report==='documents'){rows.push(['Document','Type','Lease','Property','Status','Review']);state.documents.forEach(d=>rows.push([d.name,d.type,leaseName(d.leaseId),propertyName(d.propertyId),d.status,d.expiryDate]));}else{rows.push(['Metric','Value'],['Properties',state.properties.length],['Units',state.units.length],['Occupancy',`${occupancy().rate}%`],['Active monthly rent',monthlyDue()],['Payments this month',monthPayments()],['Open billed balance',openChargeBalance()],['Municipal exposure',municipalOwing()],['Open compliance exceptions',complianceIssues().length]);}download(`MBM-${report}-report-${today()}.csv`,rows.map(r=>r.map(x=>`"${String(x??'').replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv');}
  function bindView(){
    $('#app').onclick=e=>{const button=e.target.closest('button');if(!button)return;const action=button.dataset.action;if(button.dataset.view)return setView(button.dataset.view);if(button.dataset.report){state.ui.report=button.dataset.report;save();render();return;}if(action==='form')return openForm(button.dataset.type,button.dataset.id,{propertyId:button.dataset.property,leaseId:button.dataset.lease,unitId:button.dataset.unit});if(action==='receipt')return printReceipt(button.dataset.id);if(action==='whatsapp')return whatsapp(button.dataset.id);if(action==='renewal-whatsapp')return renewalWhatsapp(button.dataset.id);if(action==='calendar-export')return exportCalendar();if(action==='municipal-export')return exportMunicipal();if(action==='history-import')return $('#historyFile').click();if(action==='cloud-signin')return window.MBMCloudV10?.signIn();if(action==='cloud-signup')return window.MBMCloudV10?.signUp();if(action==='cloud-save')return window.MBMCloudV10?.save();if(action==='cloud-load')return window.MBMCloudV10?.load();if(action==='cloud-signout')return window.MBMCloudV10?.signOut();if(action==='document-open'){const d=state.documents.find(x=>x.id===button.dataset.id);if(!window.MBMCloudV10?.openPrivateDocument)return alert('The secure document vault is unavailable. Reload the application.');return window.MBMCloudV10.openPrivateDocument(d?.storagePath).then(result=>{if(!result?.ok)alert(result?.message||'Sign in before opening the document.');});}if(action==='complete-work'){const w=state.workOrders.find(x=>x.id===button.dataset.id);w.status=w.status==='Completed'?'Open':'Completed';audit(state,'Work order status changed',`${w.title} → ${w.status}`);save();render();return;}if(action==='complete-inspection'){const i=state.inspections.find(x=>x.id===button.dataset.id);i.status=i.status==='Completed'?'Scheduled':'Completed';audit(state,'Inspection status changed',`${i.type} → ${i.status}`);save();render();return;}if(action==='backup')return backup();if(action==='export-report')return exportReport();if(action==='import')return $('#importFile').click();if(action==='migrate')return legacyMigration();if(action==='reset')return resetWorkspace();};
  }
  function backup(){audit(state,'Backup downloaded','Full V10 JSON workspace backup created.');save();download(`MBM-Property-Manager-V10-backup-${today()}.json`,JSON.stringify(state,null,2));}
  function legacyMigration(){if(!confirm('Merge available V1–V9 browser data into the V10 workspace? Existing V10 records will remain.'))return;const legacy=migrateLegacy();['properties','units','contacts','leases','payments','municipalAccounts','workOrders','inspections','documents','renewals','calendarEvents','audit'].forEach(k=>{state[k].push(...legacy[k]);});audit(state,'V1–V9 migration run','Legacy records merged into V10. Review possible duplicate records.');save('V1–V9 data merged');render();}
  function resetWorkspace(){if(!confirm('Reset only the V10 local workspace? Your older MBM browser data is not deleted. Download a backup first.'))return;state=blankState();save('V10 workspace reset');render();}
  function quickAdd(){openForm('lease');}
  $('#modalForm').addEventListener('submit',saveForm);$('#nav').addEventListener('click',e=>{const btn=e.target.closest('.nav-link');if(btn){setView(btn.dataset.view);$('#sidebar').classList.remove('open');}});$('#menuButton').onclick=()=>$('#sidebar').classList.toggle('open');$('#quickAdd').onclick=quickAdd;$('#backupButton').onclick=backup;
  $('#importFile').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const reader=new FileReader();reader.onload=()=>{try{const imported=JSON.parse(reader.result);if(!imported.version)throw new Error('Not an MBM workspace backup');state=Object.assign(blankState(),imported,{version:10});audit(state,'Backup imported',`A V${imported.version} backup replaced the current V10 workspace.`);save('Backup imported');render();}catch(err){alert(`Import failed: ${err.message}`);}};reader.readAsText(f);e.target.value='';});
  $('#historyFile').addEventListener('change',e=>{const f=e.target.files[0];if(f)importHistory(f);e.target.value='';});
  window.MBMWorkspace={getState:()=>state,replaceState:payload=>{state=Object.assign(blankState(),payload,{version:10});audit(state,'Cloud backup loaded','V10 workspace restored from private Supabase backup.');save('Cloud backup loaded');render();}};
  window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(['dashboard','calendar','portfolio','people','leases','renewals','finance','municipal','operations','documents','reports','admin'].includes(view)&&view!==state.ui.view){state.ui.view=view;render();}});
  const hash=location.hash.slice(1);if(hash)state.ui.view=hash;render();
})();
